{
  "root_cause": "The focus trap is activated only when the offcanvas scroll option is false. The page sets data-bs-scroll=\"true\", so the focus trap never activates, allowing focus to move outside the panel when Tab is pressed.",
  "repair_strategy": "Activate the focus trap unconditionally in the offcanvas show() method, keeping the existing scrollbar hiding logic unchanged.",
  "edits": [
    {
      "path": "js/src/offcanvas.js",
      "sha256": "8008243ad710528ccfdcada0687a6c260bd75c80964dcae1fa020fc9aa2e4f1d",
      "before": "    const completeCallBack = () => {\n      if (!this._config.scroll) {\n        this._focustrap.activate()\n      }\n\n      this._element.classList.add(CLASS_NAME_SHOW)\n      this._element.classList.remove(CLASS_NAME_SHOWING)\n      EventHandler.trigger(this._element, EVENT_SHOWN, { relatedTarget })\n    }",
      "after": "    const completeCallBack = () => {\n      this._focustrap.activate()\n\n      this._element.classList.add(CLASS_NAME_SHOW)\n      this._element.classList.remove(CLASS_NAME_SHOWING)\n      EventHandler.trigger(this._element, EVENT_SHOWN, { relatedTarget })\n    }"
    }
  ],
  "expected_accessibility_effect": "Focus will remain trapped inside the offcanvas when opened, allowing sequential Tab navigation to loop within the panel.",
  "functional_risks": [
    "Pages that rely on scroll=true and expect focus to escape the offcanvas may experience a change in behavior, but offcanvas is intended as a modal dialog where focus should be trapped."
  ],
  "verification_requirements": [
    "After opening the help panel, the first Tab press moves focus to the close button.",
    "A second Tab press returns focus to the close button (loop within panel).",
    "The help panel remains visible and scrollable if needed.",
    "Closing the panel with the close button or Escape restores focus to the trigger."
  ]
}
